// A Telegram update becomes the common inbound message (see assistant.ingest in db/migrations).
const profile = $('Config').first().json.profile;
const out = [];
for (const item of $('Telegram message').all()) {
  const m = item.json.message;
  if (!m || m.chat?.type !== 'private' || m.from?.is_bot) continue;  // direct chats with people only
  const from = m.from ?? {};
  const attachments = [];
  if (m.photo) attachments.push({ type: 'image', file_id: m.photo.at(-1).file_id });
  if (m.document) attachments.push({ type: 'file', file_id: m.document.file_id, name: m.document.file_name ?? null });
  if (m.voice || m.audio) attachments.push({ type: 'audio', file_id: (m.voice ?? m.audio).file_id });
  if (m.video) attachments.push({ type: 'video', file_id: m.video.file_id });
  let text = String(m.text ?? m.caption ?? '').trim();
  if (/^\/start\b/.test(text)) text = '(opened the chat)';
  // A contact shared with Telegram's own button is the sender's verified phone number.
  const shared = m.contact && m.contact.user_id === from.id ? m.contact : null;
  const phone = shared ? `+${String(shared.phone_number).replace(/\D/g, '')}` : null;
  if (shared && !text) text = `(shared their phone number: ${phone})`;
  if (!text && attachments.length) text = `(sent ${attachments.map((a) => a.type).join(', ')})`;
  if (!text) continue;
  out.push({ json: {
    profile,
    channel: 'telegram',
    external_user_id: String(m.chat.id),
    external_message_id: `${m.chat.id}:${m.message_id}`,
    sent_at: new Date(m.date * 1000).toISOString(),
    text,
    attachments,
    sender: { display_name: [from.first_name, from.last_name].filter(Boolean).join(' ') || null, username: from.username ?? null, phone, email: null },
    address: { chat_id: m.chat.id },
  } });
}
return out;
